@keyframes ring-expand {
    0% {
        opacity: .5;
        transform: translate(-50%, -50%) scale(1)
    }

    to {
        opacity: 0;
        transform: translate(-50%, -50%) scale(1.4)
    }
}

@keyframes leaf-float-1 {

    0%,
    to {
        opacity: 0;
        transform: translate(0) rotate(0deg)
    }

    10% {
        opacity: .6
    }

    50% {
        opacity: .4;
        transform: translate(-8px, 6px) rotate(45deg)
    }

    90% {
        opacity: 0
    }

    95% {
        transform: translate(-14px, 14px) rotate(90deg)
    }
}

@keyframes leaf-float-2 {

    0%,
    to {
        opacity: 0;
        transform: translate(0) rotate(0deg)
    }

    15% {
        opacity: .5
    }

    50% {
        opacity: .35;
        transform: translate(6px, -5px) rotate(-30deg)
    }

    85% {
        opacity: 0
    }

    95% {
        transform: translate(12px, -12px) rotate(-60deg)
    }
}

@keyframes leaf-float-3 {

    0%,
    to {
        opacity: 0;
        transform: translate(0) rotate(0deg)
    }

    12% {
        opacity: .55
    }

    50% {
        opacity: .3;
        transform: translate(5px, 8px) rotate(25deg)
    }

    88% {
        opacity: 0
    }

    95% {
        transform: translate(10px, 16px) rotate(50deg)
    }
}

.falling-leaves {
    height: 100vh;
    left: 0;
    overflow: hidden;
    pointer-events: none;
    position: fixed;
    top: 0;
    width: 100vw;
    z-index: 1
}

.falling-leaves__leaf {
    animation: leafFall var(--fall-duration) ease-in var(--fall-delay) forwards, leafSway var(--sway-speed) ease-in-out var(--fall-delay) infinite;
    filter: blur(.3px);
    opacity: 0;
    pointer-events: none;
    position: absolute;
    text-shadow: 0 1px 3px rgba(0, 0, 0, .15);
    top: -40px;
    will-change: transform, opacity
}

@keyframes leafFall {
    0% {
        opacity: 0;
        transform: translateY(0) translateX(0) rotate(var(--rotate-start))
    }

    5% {
        opacity: var(--leaf-opacity)
    }

    85% {
        opacity: var(--leaf-opacity)
    }

    to {
        opacity: 0;
        transform: translateY(calc(100vh + 60px)) translateX(var(--drift-x)) rotate(var(--rotate-end))
    }
}

@keyframes leafSway {

    0%,
    to {
        margin-left: 0
    }

    25% {
        margin-left: calc(var(--sway-amount)*.6)
    }

    50% {
        margin-left: calc(var(--sway-amount)*-.4)
    }

    75% {
        margin-left: calc(var(--sway-amount)*.3)
    }
}

