@keyframes blinking {
    50% {
        opacity: 0
    }
}

@keyframes bouncingLeft {
    0% {
        transform: translateX(0)
    }

    20% {
        transform: translateX(-5%)
    }

    40% {
        transform: translateX(-2%)
    }

    60% {
        transform: translateX(-6%)
    }

    80% {
        transform: translateX(0)
    }

    to {
        transform: translateX(0)
    }
}

@keyframes spin {
    0% {
        transform: rotate(0deg)
    }

    to {
        transform: rotate(1turn)
    }
}

@keyframes slideFromLeft {
    0% {
        -webkit-transform: translate3d(-100%, 0, 0);
        transform: translate3d(-100%, 0, 0);
        visibility: visible
    }

    to {
        -webkit-transform: translateZ(0);
        transform: translateZ(0)
    }
}

@keyframes slideFromRight {
    0% {
        -webkit-transform: translate3d(100%, 0, 0);
        transform: translate3d(100%, 0, 0);
        visibility: visible
    }

    to {
        -webkit-transform: translateZ(0);
        transform: translateZ(0)
    }
}

@keyframes slideToTheLeft {
    0% {
        -webkit-transform: translateZ(0);
        transform: translateZ(0);
        visibility: visible
    }

    to {
        -webkit-transform: translate3d(-100vw, 0, 0);
        transform: translate3d(-100vw, 0, 0)
    }
}

@keyframes slideFromBottomLeftCorner {
    0% {
        transform: translate3d(-100%, 100%, 0);
        visibility: visible
    }

    to {
        transform: translateZ(0)
    }
}

@keyframes slideFromTopRightCorner {
    0% {
        transform: translate3d(100%, -100%, 0);
        visibility: visible
    }

    to {
        transform: translateZ(0)
    }
}

@keyframes scaleFromZeroWithBounce {
    0% {
        transform: scale(0);
        visibility: visible
    }

    80% {
        transform: scale(1.1)
    }

    to {
        transform: scale(1)
    }
}

@keyframes scaleSmallBounce {
    0% {
        transform: scale(1)
    }

    80% {
        transform: scale(1.1)
    }

    to {
        transform: scale(1)
    }
}

@keyframes customGlassSlide {
    0% {
        transform: translateZ(0);
        visibility: visible
    }

    50% {
        transform: translate3d(0, 30px, 0)
    }

    to {
        transform: translateZ(0)
    }
}

@keyframes fillAnimation {
    0% {
        width: 0
    }

    to {
        width: 100%
    }
}

